cat > src/ProfileSettings.css <<'EOF'
.profile-settings {
  max-width: 720px;
  margin: 0 auto;
  padding: 32px 24px 48px;
}

.profile-settings__section {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.profile-settings__row {
  display: grid;
  grid-template-columns: 200px minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.profile-settings__row-label {
  padding-top: 6px;
}

.profile-settings__row-hint {
  display: block;
  margin-top: 4px;
}

.profile-settings__avatar {
  display: flex;
  align-items: center;
  gap: 16px;
}

.profile-settings__avatar-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.profile-settings__checkbox-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.profile-settings__footer {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-top: 8px;
}

@media (max-width: 600px) {
  .profile-settings__row {
    grid-template-columns: 1fr;
    gap: 6px;
  }
  .profile-settings__row-label {
    padding-top: 0;
  }
}
EOF
